class LoginBloc
  include Observable
  attr_reader :state                # @state = { status: :idle }
  def dispatch(event)
    case [@state[:status], event[:type]]
    when [:idle, :submit] then @state = { status: :busy }
    when [:busy, :failed] then @state = { status: :error, reason: event[:reason] }
    when [:busy, :ok]     then @state = { status: :ok }
    end
    changed; notify_observers(@state)   # mark dirty, then fan out
  end
end
